steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
    query {
      issues(filter: {
        priority: { eq: 2 },
        state: { type: { eq: BUG } }
      }) {
        nodes {
          id
          identifier
          title
          priority
          assignee {
            name
            id
          }
          team {
            name
            id
          }
          workflowState {
            name
            id
            type
          }
        }
      }
    }
  "'
